any.script:
var br = tree.root.get_node_or_null("/root/Main/BoardRoot")
if br == null:
	return false
for c in br.get_children():
	var scr = c.get_script()
	if scr != null and "DisembarkController" in str(scr.resource_path):
		return true
return false

items.script:
var pi = PhaseManager.current_phase_instance
if pi == null or not pi.has_method("get_active_move_data"):
	return false
var md = pi.get_active_move_data("U_BOYZ_T")
if typeof(md) != TYPE_DICTIONARY:
	return false
for d in md.get("model_distances", {}).values():
	if float(d) > 0.01:
		return true
return false

